CREATE OR REPLACE FUNCTION calculate_rcp(p_vehiclereg VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    v_distdonekm NUMERIC;
    v_distleftkm NUMERIC;
    v_rcp NUMERIC;
BEGIN
    SELECT distdonekm, distleftkm INTO v_distdonekm, v_distleftkm
    FROM transportinfo
    WHERE vehiclereg = p_vehiclereg
    LIMIT 1;

    IF (v_distdonekm + v_distleftkm) = 0 THEN
        v_rcp := 0;
    ELSE
        v_rcp := (v_distdonekm / (v_distdonekm + v_distleftkm)) * 100;
    END IF;

    RETURN v_rcp;
END;
$$ LANGUAGE plpgsql;
